import pandas as pd,numpy as np
from sklearn.base import BaseEstimator,TransformerMixin
from sklearn.preprocessing import OneHotEncoder,StandardScaler,FunctionTransformer
from sklearn.compose import ColumnTransformer
from sklearn.pipeline import make_pipeline
from sklearn.linear_model import Ridge,LinearRegression
from sklearn.model_selection import RepeatedKFold
tr=pd.read_csv('alloy_pair_constrained_train.csv');p=pd.read_csv('alloy_pair_constrained_pool.csv');y=tr.pop('target');ids=p.pop('candidate_id')
cat=['heat_treatment','route']; comp=['Cr','Ni','Mo','V','Nb','Co','Ti']; proc=['solutionizing_temp','aging_temp','aging_time','cooling_rate']; nums=comp+proc
folds=list(RepeatedKFold(n_splits=5,n_repeats=5,random_state=391).split(tr))
def fun(kind):
 def f(X):
  X=np.asarray(X); blocks=[]
  if 'x' in kind:blocks.append(X)
  if '2' in kind:blocks.append(X**2)
  if '3' in kind:blocks.append(X**3)
  if 'sqrt' in kind:blocks.append(np.sqrt(np.maximum(X,0)))
  if 'log' in kind:blocks.append(np.log1p(np.maximum(X,0)))
  return np.hstack(blocks)
 return FunctionTransformer(f)
def model(ckind,pkind,alpha):
 return make_pipeline(ColumnTransformer([('comp',make_pipeline(fun(ckind),StandardScaler()),comp),('proc',make_pipeline(fun(pkind),StandardScaler()),proc),('cat',OneHotEncoder(),cat)]),Ridge(alpha=alpha))
def cv(m):
 ss=n=0
 for a,b in folds:m.fit(tr.iloc[a],y.iloc[a]);e=y.iloc[b]-m.predict(tr.iloc[b]);ss+=e@e;n+=len(e)
 return (ss/n)**.5
for ck in [('x','2'),('x','2','sqrt'),('x','2','log'),('x','2','sqrt','log'),('x','2','3','sqrt'),('x','2','3','sqrt','log')]:
 for pk in [('x','2'),('x','2','3')]:
  z=[]
  for a in [.01,.1,.3,1,3,10]:z.append((a,cv(model(ck,pk,a))))
  print(ck,pk,min(z,key=lambda a:a[1]),z)
# preds best
for ck in [('x','2','sqrt'),('x','2','log'),('x','2','sqrt','log'),('x','2','3','sqrt')]:
 m=model(ck,('x','2'),.3);m.fit(tr,y)
 print(ck,dict(zip(ids,m.predict(p))).__str__()[:0],pd.Series(m.predict(p),index=ids).loc[['c092','c029','c044','c068','c019','c075','c082','c007','c080']].round(2).to_dict())
